//! Owns one device-local history row for an accepted live connection attempt.

use crate::inventory::{Inventory, RecentSessionKind, RecentSessionOutcome, SessionError};

/// Closes a history row even when its owning connection future is cancelled.
/// The identifier is generated by the local store and is distinct from any
/// frontend transport identifier.
pub struct SessionHistoryLease<F: Fn(&str) + Send + Sync> {
    inventory: Inventory,
    id: String,
    on_closed: F,
    ended: bool,
}

impl<F: Fn(&str) + Send + Sync> SessionHistoryLease<F> {
    /// Record an accepted connection attempt against a live login.
    ///
    /// # Errors
    ///
    /// Rejects a missing login or local storage failure without creating a
    /// usable lease.
    pub fn start(
        inventory: Inventory,
        profile_id: String,
        kind: RecentSessionKind,
        on_closed: F,
    ) -> Result<Self, SessionError> {
        let opened = inventory.open_session(profile_id, kind)?;
        Ok(Self { inventory, id: opened.id, on_closed, ended: false })
    }

    /// The history UUIDv7 generated by the local store.
    #[must_use]
    pub fn id(&self) -> &str {
        &self.id
    }

    /// Record a terminal outcome after all connection work has completed.
    ///
    /// # Errors
    ///
    /// Propagates a storage failure. The drop fallback retries with `Failed`.
    pub fn finish(mut self, outcome: RecentSessionOutcome) -> Result<(), SessionError> {
        self.close(outcome)
    }

    fn close(&mut self, outcome: RecentSessionOutcome) -> Result<(), SessionError> {
        self.inventory.close_session(self.id.clone(), outcome)?;
        self.ended = true;
        (self.on_closed)(&self.id);
        Ok(())
    }
}

impl<F: Fn(&str) + Send + Sync> Drop for SessionHistoryLease<F> {
    fn drop(&mut self) {
        if !self.ended {
            let _ = self.close(RecentSessionOutcome::Failed);
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::sync::{Arc, Mutex};

    use crate::inventory::{NewHost, SignIn};
    use crate::store::Store;
    use scoplen_crypto::LocalDatabaseKey;

    fn fixture() -> (Inventory, String, tempfile::TempDir) {
        let dir = tempfile::tempdir().expect("temporary store");
        let store = Store::open(&dir.path().join("local.db"), &LocalDatabaseKey::new([7; 32]))
            .expect("encrypted store");
        let inventory = Inventory::new(Arc::new(store));
        let host = inventory
            .add_host(NewHost {
                name: Some("api".into()),
                address: "api.example".into(),
                port: None,
                username: "ops".into(),
                sign_in: SignIn::Agent,
            })
            .expect("live login");
        (inventory, host.logins[0].id.clone(), dir)
    }

    #[test]
    fn accepted_attempt_uses_store_uuid_and_records_closed_outcome() {
        let (inventory, profile, dir) = fixture();
        let events = Arc::new(Mutex::new(Vec::new()));
        let changes = events.clone();
        let lease = SessionHistoryLease::start(
            inventory.clone(),
            profile,
            RecentSessionKind::Terminal,
            move |id| changes.lock().expect("events").push(id.to_owned()),
        )
        .expect("accepted attempt");
        let history_id = lease.id().to_owned();
        assert_eq!(uuid::Uuid::parse_str(&history_id).expect("UUID").get_version_num(), 7);
        let recent = inventory.recent_sessions().expect("recent");
        assert_eq!(recent.len(), 1);
        assert_eq!(recent[0].id, history_id);
        assert_eq!(recent[0].outcome, None);

        lease.finish(RecentSessionOutcome::Closed).expect("close history");
        let recent = inventory.recent_sessions().expect("recent");
        assert_eq!(recent[0].outcome, Some(RecentSessionOutcome::Closed));
        assert!(recent[0].ended_at.is_some());
        assert_eq!(*events.lock().expect("events"), vec![history_id]);
        drop(inventory);
        drop(dir);
    }

    #[test]
    fn rejected_profile_does_not_create_history_or_event() {
        let (inventory, _, dir) = fixture();
        let events = Arc::new(Mutex::new(Vec::new()));
        let changes = events.clone();
        assert!(
            SessionHistoryLease::start(
                inventory.clone(),
                "not-a-uuid".into(),
                RecentSessionKind::Terminal,
                move |id| changes.lock().expect("events").push(id.to_owned()),
            )
            .is_err()
        );
        assert!(inventory.recent_sessions().expect("recent").is_empty());
        assert!(events.lock().expect("events").is_empty());
        drop(inventory);
        drop(dir);
    }

    #[test]
    fn aborted_owner_future_records_failed_outcome() {
        let (inventory, profile, dir) = fixture();
        let events = Arc::new(Mutex::new(Vec::new()));
        let changes = events.clone();
        let runtime =
            tokio::runtime::Builder::new_current_thread().enable_all().build().expect("runtime");
        let history_id = runtime.block_on(async {
            let (started, ready) = tokio::sync::oneshot::channel();
            let task = tokio::spawn({
                let inventory = inventory.clone();
                async move {
                    let lease = SessionHistoryLease::start(
                        inventory,
                        profile,
                        RecentSessionKind::Terminal,
                        move |id| changes.lock().expect("events").push(id.to_owned()),
                    )
                    .expect("accepted attempt");
                    let _ = started.send(lease.id().to_owned());
                    std::future::pending::<()>().await;
                    drop(lease);
                }
            });
            let id = ready.await.expect("started");
            task.abort();
            assert!(task.await.expect_err("cancelled").is_cancelled());
            id
        });
        let recent = inventory.recent_sessions().expect("recent");
        assert_eq!(recent.len(), 1);
        assert_eq!(recent[0].id, history_id);
        assert_eq!(recent[0].outcome, Some(RecentSessionOutcome::Failed));
        assert!(recent[0].ended_at.is_some());
        assert_eq!(*events.lock().expect("events"), vec![history_id]);
        drop(inventory);
        drop(dir);
    }
}
